import{_ as h,l as n,o as e,c as i,v as t,p as o,x as m,d as l,i as d,S as s}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"gamma-theta 权衡","description":"","frontmatter":{"title":"gamma-theta 权衡","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gamma-theta-tradeoff.md","filePath":"quant/gamma-theta-tradeoff.md","lastUpdated":1789023840000}'),p={name:"quant/gamma-theta-tradeoff.md"};function c(E,a,f,T,g,u){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="gamma-theta-权衡" tabindex="-1">gamma-theta 权衡 <a class="header-anchor" href="#gamma-theta-权衡" aria-label="Permalink to &quot;gamma-theta 权衡&quot;">​</a></h1><div class="epigraph"><p>持有期权的 Theta 是你为 Gamma 付的租金；已实现波动若高于隐含，租金才赚得回来。</p><footer>—— 对照 Taleb 对期权动态对冲的叙述；BSM 方程里 $\\Theta+\\tfrac12\\sigma^2 S^2\\Gamma$ 与利率项的平衡</footer></div><p><a href="/quant/iv-surface-dynamics">上一课</a>把曲面因子写进情景。本课回到单日 PnL 的会计：<strong>Gamma 赚已实现、Theta 付隐含。</strong> 主干 <a href="/quant/discrete-hedge-error">离散对冲误差</a> 与 <a href="/quant/greeks-hedge">Greeks 对冲</a> 已写复制误差。缺口是把 BSM 的瞬时恒等式当成交易员的日 PnL 分解，并写清微笑与跳如何让恒等式破损。后课模型风险把「隐含 vs 已实现」升成模型选择。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Delta 对冲后，BSM 世界里瞬时</p> \\[\\mathrm{d}V-\\Delta\\mathrm{d}S \\approx \\Theta\\mathrm{d}t+\\tfrac12\\Gamma(\\mathrm{d}S)^2+\\cdots \\]<p>而定价时 \\(\\Theta+\\tfrac12\\sigma_{\\mathrm{imp}}^2 S^2\\Gamma\\approx r(V-\\Delta S)\\)（略去股息）。于是超额 PnL 大约是 \\(\\tfrac12 S^2\\Gamma\\bigl((\\mathrm{d}S/S)^2-\\sigma_{\\mathrm{imp}}^2\\mathrm{d}t\\bigr)\\)。多 Gamma 的人在已实现方差高于隐含方差时赚钱。问题是：这是<strong>对冲后的方差互换型暴露</strong>，不是「方向对了」；微笑下每个 \\(K\\) 的 \\(\\sigma_{\\mathrm{imp}}\\) 不同，总 Gamma 加权平均的隐含方差才是你付的租金。把 ATM 隐波当所有腿的租金，会在偏斜产品上把账做平。</p><p>Theta 还含利率与时间衰减的会计项。周末、节假日的日历 Theta 与交易日已实现不对齐，见 <a href="/quant/calendar-overnight">日历与隔夜</a>。</p><h3 id="跳让-gamma-租金变成数字风险" tabindex="-1">跳让 Gamma 租金变成数字风险 <a class="header-anchor" href="#跳让-gamma-租金变成数字风险" aria-label="Permalink to &quot;跳让 Gamma 租金变成数字风险&quot;">​</a></h3><p>连续路径下 \\((\\mathrm{d}S)^2\\) 与 \\(\\sigma^2\\mathrm{d}t\\) 比。跳来时 \\((\\Delta S)^2\\) 很大，Gamma 近似失效，PnL 由跳跃大小与期权凸性的离散差决定。卖方若靠收 Theta 过日子，是在卖跳。这与 <a href="/quant/variance-swap-vix">方差互换</a> 的跳修正是同一件事，只是名义换成了你簿上的 \\(\\Gamma(K)\\) 分布。</p><p><span class="marginnote">Gamma 的符号在障碍附近可以与香草相反。敲出前多 Gamma、敲出后归零，Theta 仍在收，权衡在壁附近不是平稳的日租金。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>日终分解：Delta PnL、Gamma/已实现、Theta/隐含、Vega/曲面变化、残余（高阶、跳、费用）。已实现用与对冲频率一致的采样，不要用日度平方去解释五分钟对冲的簿。对冲频率提高，已实现更接近二次变差，也更吃微观结构噪声，见 <a href="/quant/rv-noise">已实现波动与噪声</a>。</p><p>限额：用 \\(\\tfrac12 S^2\\Gamma\\) 当方差名义，对比隐含方差与预测 RV。这是把期权簿翻译成方差互换语言，便于和 <a href="/quant/har-rv">HAR</a> 一类预测对表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>你买凸性，就得付时间。市场通过隐波收这份租金。若你的对冲把方向拿走，剩下的赌注是二次变差对隐含方差。曲面因子动时，Vega PnL 会盖过 Gamma-Theta；那不是权衡失效，是你还暴露在 Cont–da Fonseca 的水平上。先把 Vega 对冲到桶限额内，Gamma-Theta 才读得出来。</p>',16)),(e(),o(s,null,{default:m(()=>[d(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20DH%5B%22Delta%20%E5%AF%B9%E5%86%B2%E5%90%8E%22%5D%20--%3E%20GT%5B%22Gamma%20%E4%B9%98%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%96%B9%E5%B7%AE%22%5D%0A%20%20DH%20--%3E%20Th%5B%22Theta%20%E4%BB%98%E9%9A%90%E5%90%AB%E6%96%B9%E5%B7%AE%22%5D%0A%20%20GT%20--%3E%20Edge%5B%22%E5%B7%AE%E6%98%AF%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%E5%9E%8B%20PnL%22%5D%0A%20%20Th%20--%3E%20Edge%0A%20%20Jump%5B%22%E8%B7%B3%22%5D%20--%3E%20Break%5B%22Gamma%20%E8%BF%91%E4%BC%BC%E7%A0%B4%E8%A3%82%22%5D%0A"})]),fallback:m(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>离散对冲、买卖价差、隔夜缺口使恒等式只是分解框架，不是保证。美式提前行权、融资与股票借券进入 carry，不在纯 \\(\\Gamma\\)–\\(\\Theta\\) 里。结构产品的「Theta」往往含障碍时间流逝，符号与香草相反，不要用同一句「卖方收租」概括 autocallable。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Delta 对冲后，多 Gamma 赚已实现减隐含；租金应按簿上 \\(\\Gamma(K)\\) 加权的隐波来算。</li><li>跳与障碍让瞬时恒等式破裂。</li><li>先把 Vega 桶对冲掉，再读 Gamma-Theta，否则被曲面因子淹没。</li><li>出处：BSM 方程的 \\(\\Theta\\)–\\(\\Gamma\\) 平衡；Taleb, <em>Dynamic Hedging</em>；跳与方差复制见 Carr–Madan。</li></ul>',4))])}const G=h(p,[["render",c]]);export{_ as __pageData,G as default};
